        Keyboard = 2,
        Autostart = 3,
        Quit = 4,
    }

    /// <summary>Tailles disponibles, en pixels, par ordre croissant.</summary>
    public static readonly int[] Sizes = [16, 20, 24, 32];

    // Ordre : icone majeure, taille mineure.
