    private static readonly byte[]?[] Cache = new byte[]?[Encoded.Length];

    /// <summary>La taille disponible la plus proche de celle demandee.</summary>
    public static int NearestSize(int requested)
    {
        int best = Sizes[0];
        int bestGap = System.Math.Abs(requested - best);

        foreach (int size in Sizes)
        {
            int gap = System.Math.Abs(requested - size);
            if (gap < bestGap)
            {
                best = size;
                bestGap = gap;
            }
        }

        return best;
    }

    /// <summary>Couvertures alpha, une par pixel, balayees ligne par ligne.</summary>
    public static byte[] Mask(Icon icon, int size)
    {
        int sizeIndex = System.Array.IndexOf(Sizes, size);
        if (sizeIndex < 0)
        {
            throw new System.ArgumentOutOfRangeException(nameof(size));
        }

        int index = ((int)icon * Sizes.Length) + sizeIndex;
        return Cache[index] ??= System.Convert.FromBase64String(Encoded[index]);
    }
